package io.github.diodeme.ji.provider.http;

import java.time.Duration;

/** Shared outbound provider HTTP limits. No total generation deadline is imposed. */
public record ProviderHttpPolicy(
        Duration connectTimeout,
        Duration firstByteTimeout,
        Duration streamIdleTimeout,
        int maxRetries,
        Duration maxRetryDelay) {
    public static final ProviderHttpPolicy DEFAULT = new ProviderHttpPolicy(
            Duration.ofSeconds(15), Duration.ofSeconds(120), Duration.ofSeconds(120), 2, Duration.ofSeconds(30));

    public ProviderHttpPolicy {
        requirePositive(connectTimeout, "connectTimeout");
        requirePositive(firstByteTimeout, "firstByteTimeout");
        requirePositive(streamIdleTimeout, "streamIdleTimeout");
        if (maxRetries < 0 || maxRetries > 2) throw new IllegalArgumentException("maxRetries must be between 0 and 2");
        requirePositive(maxRetryDelay, "maxRetryDelay");
    }

    private static void requirePositive(Duration value, String name) {
        if (value == null || value.isZero() || value.isNegative()) {
            throw new IllegalArgumentException(name + " must be positive");
        }
    }
}
